svg.script:
(function() {
  var frame = document.getElementById('daw-frame');
  var doc = frame.contentWindow.document;
  var cdnBase = 'https://jsdelivr.net';

  var bootHtml = [
    '<!DOCTYPE html>',
    '<html><head><meta charset="utf-8">',
    '<base href="' + cdnBase + '">',
    '<style>html,body{margin:0;padding:0;width:100%;height:100%;background:#111;color:#eee;font-family:sans-serif;overflow:hidden;}</style>',
    '<script>',
    '  (function(){',
    '    var mem = {};',
    '    try { window.localStorage.getItem("test"); } catch(e) {',
    '      Object.defineProperty(window, "localStorage", {',
    '        value: {',
    '          getItem: function(k){ return mem.hasOwnProperty(k) ? mem[k] : null; },',
    '          setItem: function(k,v){ mem[k] = String(v); },',
    '          removeItem: function(k){ delete mem[k]; },',
    '          clear: function(){ mem = {}; }',
    '        }',
    '      });',
    '    }',
    '  })();',
    '<\/script>',
    '</head><body>',
    '<div id="boot-msg" style="display:flex;align-items:center;justify-content:center;height:100%;">Loading AudioMass...</div>',
    '</body></html>'
  ].join('\n');

  doc.open();
  doc.write(bootHtml);
  doc.close();

  fetch(cdnBase + 'index.html')
    .then(function(r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return r.text();
    })
    .then(function(htmlText) {
      var parser = new DOMParser();
      var parsed = parser.parseFromString(htmlText, 'text/html');

      parsed.querySelectorAll('link[rel="stylesheet"]').forEach(function(link) {
        var newLink = doc.createElement('link');
        newLink.rel = 'stylesheet';
        newLink.href = new URL(link.getAttribute('href'), cdnBase).href;
        doc.head.appendChild(newLink);
      });

      var scripts = Array.from(parsed.querySelectorAll('script'));
      parsed.querySelectorAll('script').forEach(function(s) { s.remove(); });
      doc.body.innerHTML = parsed.body.innerHTML;

      function loadNext(idx) {
        if (idx >= scripts.length) {
          var ev = doc.createEvent('Event');
          ev.initEvent('DOMContentLoaded', true, true);
          doc.dispatchEvent(ev);
          return;
        }
        var oldS = scripts[idx];
        var newS = doc.createElement('script');
        var src = oldS.getAttribute('src');
        if (src) {
          newS.src = new URL(src, cdnBase).href;
          newS.async = false;
          newS.onload = function() { loadNext(idx + 1); };
          newS.onerror = function() { loadNext(idx + 1); };
          doc.body.appendChild(newS);
        } else {
          newS.textContent = oldS.textContent;
          doc.body.appendChild(newS);
          loadNext(idx + 1);
        }
      }

      loadNext(0);
    })
    .catch(function(err) {
      var el = doc.getElementById('boot-msg');
      if (el) el.textContent = 'Load error: ' + err.message;
    });
})();
